'use client';

import { useEffect, useMemo, useState } from 'react';

import { loadPersistedAnalyticsFilters, persistAnalyticsFilters } from '../filterPersistence';

import type { BranchOption, OverviewResponse, PeriodPreset, TrendChartData } from './types';

import { addDaysToDateString, todayDateString } from '@/lib/time';

export function useAdminAnalyticsOverviewData() {
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [periodPreset, setPeriodPreset] = useState<PeriodPreset>('30');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [branchId, setBranchId] = useState<string>('all');
    const [branches, setBranches] = useState<BranchOption[]>([]);
    const [data, setData] = useState<OverviewResponse['data'] | null>(null);
    const [reloadKey, setReloadKey] = useState(0);

    useEffect(() => {
        const endDefault = todayDateString();
        const startDefault = addDaysToDateString(endDefault, -30);
        const persisted = loadPersistedAnalyticsFilters();

        setStartDate(persisted.startDate ?? startDefault);
        setEndDate(persisted.endDate ?? endDefault);
        if (persisted.branchId) {
            setBranchId(persisted.branchId);
        }
    }, []);

    useEffect(() => {
        let ignore = false;

        async function loadBranches() {
            try {
                const response = await fetch('/api/admin/branches/list', { cache: 'no-store' });
                if (!response.ok) return;

                const json = (await response.json()) as { ok?: boolean; data?: BranchOption[] };
                if (!json.ok || !Array.isArray(json.data)) return;

                if (!ignore) {
                    setBranches(json.data);
                }
            } catch {
                // Branch filter is optional; leave it empty on failure.
            }
        }

        void loadBranches();
        return () => {
            ignore = true;
        };
    }, []);

    useEffect(() => {
        if (!startDate || !endDate) return;
        let ignore = false;

        async function loadOverview() {
            try {
                setLoading(true);
                setError(null);

                const params = new URLSearchParams();
                params.set('startDate', startDate);
                params.set('endDate', endDate);
                if (branchId && branchId !== 'all') {
                    params.set('branchIds', branchId);
                }

                const response = await fetch(`/admin/api/analytics/overview?${params.toString()}`, {
                    cache: 'no-store',
                });
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}`);
                }

                const json = (await response.json()) as OverviewResponse;
                if (!json.ok || !json.data) {
                    throw new Error(json.error || 'Не удалось загрузить данные обзора');
                }

                if (!ignore) {
                    setData(json.data);
                }
            } catch (value) {
                if (!ignore) {
                    setError(value instanceof Error ? value.message : String(value));
                }
            } finally {
                if (!ignore) {
                    setLoading(false);
                }
            }
        }

        void loadOverview();
        return () => {
            ignore = true;
        };
    }, [branchId, endDate, reloadKey, startDate]);

    useEffect(() => {
        if (!startDate || !endDate) return;
        persistAnalyticsFilters({
            startDate,
            endDate,
            branchId,
        });
    }, [branchId, endDate, startDate]);

    const trendChartData = useMemo<TrendChartData | null>(() => {
        if (!data) return null;

        return {
            bookings: data.byDay.map((point) => ({ x: point.date, y: point.bookingsConfirmedOrPaid })),
            revenue: data.byDay.map((point) => ({ x: point.date, y: point.totalRevenue })),
            promoShare: data.byDay.map((point) => {
                const total = point.bookingsConfirmedOrPaid || 0;
                const promo = point.promoBookings || 0;
                const share = total > 0 ? Math.round(((promo / total) * 100 + Number.EPSILON) * 100) / 100 : 0;
                return { x: point.date, y: share };
            }),
        };
    }, [data]);

    const promoShare =
        data && data.summary.revenue.total > 0 && data.summary.revenue.promoRevenue > 0
            ? Math.round(((data.summary.revenue.promoRevenue / data.summary.revenue.total) * 100 + Number.EPSILON) * 100) / 100
            : 0;

    const handlePresetChange = (preset: PeriodPreset) => {
        setPeriodPreset(preset);
        if (preset === 'custom') return;

        const days = preset === '7' ? 7 : preset === '30' ? 30 : 90;
        const end = todayDateString();
        const start = addDaysToDateString(end, -days);
        setStartDate(start);
        setEndDate(end);
    };

    const retry = () => {
        setError(null);
        setLoading(true);
        setReloadKey((value) => value + 1);
    };

    return {
        loading,
        error,
        periodPreset,
        startDate,
        endDate,
        branchId,
        branches,
        data,
        trendChartData,
        promoShare,
        setBranchId,
        handlePresetChange,
        retry,
        setStartDateAndCustom: (value: string) => {
            setStartDate(value);
            setPeriodPreset('custom');
        },
        setEndDateAndCustom: (value: string) => {
            setEndDate(value);
            setPeriodPreset('custom');
        },
    };
}

'use client';

import {
    AdminAnalyticsFiltersSection,
    AdminAnalyticsKpiSection,
    AdminAnalyticsOverviewError,
    AdminAnalyticsOverviewLoading,
    AdminAnalyticsTrendsSection,
} from './AdminAnalyticsOverviewSections';
import { useAdminAnalyticsOverviewData } from './useAdminAnalyticsOverviewData';

export default function AdminAnalyticsOverviewPage() {
    const {
        loading,
        error,
        periodPreset,
        startDate,
        endDate,
        branchId,
        branches,
        data,
        trendChartData,
        promoShare,
        setBranchId,
        handlePresetChange,
        retry,
        setStartDateAndCustom,
        setEndDateAndCustom,
    } = useAdminAnalyticsOverviewData();

    if (loading && !data) {
        return <AdminAnalyticsOverviewLoading />;
    }

    if (error) {
        return <AdminAnalyticsOverviewError error={error} onRetry={retry} />;
    }

    if (!data) {
        return null;
    }

    return (
        <div className="space-y-6 py-6">
            <AdminAnalyticsFiltersSection
                periodPreset={periodPreset}
                onPresetChange={handlePresetChange}
                startDate={startDate}
                endDate={endDate}
                onStartDateChange={setStartDateAndCustom}
                onEndDateChange={setEndDateAndCustom}
                branchId={branchId}
                onBranchIdChange={setBranchId}
                branches={branches}
            />

            <AdminAnalyticsKpiSection summary={data.summary} promoShare={promoShare} />

            <AdminAnalyticsTrendsSection trendChartData={trendChartData} byDay={data.byDay} />
        </div>
    );
}

'use client';

import type { BranchOption, OverviewByDayPoint, OverviewSummary, PeriodPreset, TrendChartData } from './types';

import { AlertBanner } from '@/components/ui/AlertBanner';
import { Button } from '@/components/ui/Button';
import { EmptyState } from '@/components/ui/EmptyState';

function formatNumber(value: number) {
    return value.toLocaleString('ru-RU');
}

function formatCurrencyKGS(value: number) {
    return new Intl.NumberFormat('ru-RU', {
        style: 'currency',
        currency: 'KGS',
        maximumFractionDigits: 0,
    }).format(value);
}

export function AdminAnalyticsOverviewLoading() {
    return (
        <div className="px-4 py-10">
            <div className="flex items-center justify-center">
                <div className="inline-flex items-center gap-3 px-4 py-2 rounded-full bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 shadow-sm">
                    <div className="h-4 w-4 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                    <span className="text-sm text-gray-600 dark:text-gray-300">Загружаем обзор аналитики...</span>
                </div>
            </div>
        </div>
    );
}

export function AdminAnalyticsOverviewError({
    error,
    onRetry,
}: {
    error: string;
    onRetry: () => void;
}) {
    return (
        <div className="px-4 py-10">
            <div className="mx-auto max-w-xl">
                <AlertBanner
                    variant="danger"
                    title="Ошибка загрузки обзора"
                    message={error}
                    action={
                        <Button type="button" variant="danger" size="sm" onClick={onRetry}>
                            Попробовать снова
                        </Button>
                    }
                />
            </div>
        </div>
    );
}

export function AdminAnalyticsFiltersSection({
    periodPreset,
    onPresetChange,
    startDate,
    endDate,
    onStartDateChange,
    onEndDateChange,
    branchId,
    onBranchIdChange,
    branches,
}: {
    periodPreset: PeriodPreset;
    onPresetChange: (preset: PeriodPreset) => void;
    startDate: string;
    endDate: string;
    onStartDateChange: (value: string) => void;
    onEndDateChange: (value: string) => void;
    branchId: string;
    onBranchIdChange: (value: string) => void;
    branches: BranchOption[];
}) {
    return (
        <section className="bg-white dark:bg-gray-900 rounded-2xl border border-gray-200 dark:border-gray-800 shadow-sm p-6 space-y-4">
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                <div>
                    <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">Фильтры</h2>
                    <p className="text-xs text-gray-500 dark:text-gray-400">
                        Период и филиал задают срез для всех метрик и трендов.
                    </p>
                </div>
            </div>

            <div className="grid gap-4 md:grid-cols-3 lg:grid-cols-4">
                <div className="space-y-2">
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-300 uppercase tracking-wide">Период</p>
                    <div className="inline-flex rounded-full bg-gray-100 dark:bg-gray-800 p-1 text-xs font-medium">
                        {(['7', '30', '90', 'custom'] as PeriodPreset[]).map((preset) => (
                            <button
                                key={preset}
                                type="button"
                                onClick={() => onPresetChange(preset)}
                                className={`px-3 py-1 rounded-full transition-colors ${
                                    periodPreset === preset
                                        ? 'bg-white dark:bg-gray-900 text-indigo-600 dark:text-indigo-400 shadow-sm'
                                        : 'text-gray-600 dark:text-gray-300 hover:text-indigo-600 dark:hover:text-indigo-400'
                                }`}
                            >
                                {preset === '7' && '7 дней'}
                                {preset === '30' && '30 дней'}
                                {preset === '90' && '90 дней'}
                                {preset === 'custom' && 'Кастомный'}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="space-y-2">
                    <label className="block text-xs font-medium text-gray-600 dark:text-gray-300 uppercase tracking-wide">
                        Дата начала
                    </label>
                    <input
                        type="date"
                        value={startDate}
                        onChange={(event) => onStartDateChange(event.target.value)}
                        className="w-full px-3 py-2 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    />
                </div>

                <div className="space-y-2">
                    <label className="block text-xs font-medium text-gray-600 dark:text-gray-300 uppercase tracking-wide">
                        Дата окончания
                    </label>
                    <input
                        type="date"
                        value={endDate}
                        onChange={(event) => onEndDateChange(event.target.value)}
                        className="w-full px-3 py-2 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    />
                </div>

                <div className="space-y-2">
                    <label className="block text-xs font-medium text-gray-600 dark:text-gray-300 uppercase tracking-wide">
                        Филиал
                    </label>
                    <select
                        value={branchId}
                        onChange={(event) => onBranchIdChange(event.target.value)}
                        className="w-full px-3 py-2 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-sm text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                    >
                        <option value="all">Все филиалы</option>
                        {branches.map((branch) => (
                            <option key={branch.id} value={branch.id}>
                                {branch.name}
                            </option>
                        ))}
                    </select>
                </div>
            </div>
        </section>
    );
}

export function AdminAnalyticsKpiSection({
